with a as(select * from public.authors where open_library_id=any(array['OL8267741A','OL2628905A','OL7694495A']::text[])),w as(select * from public.works where open_library_id=any(array['OL24409454W','OL35011674W','OL20302179W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9789403160405','9789046705223','9789023486381']::text[]) or open_library_edition_id=any(array['OL32329909M','OL26374447M','OL27504672M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987119001 and 987119999),'editions',(select count(*) from public.editions where id between 987219001 and 987219999),'authors',(select count(*) from public.authors where id between 987319001 and 987319999))) as preflight;
